        getChartData(state) {
            var self = this;
            var labels = state.domainState.scoreHistory.map(function(_, i) { return self._t('document_label') + ' ' + (i + 1); });
            return {
                scoreChart: {
                    labels: labels,
                    datasets: [{ data: state.domainState.scoreHistory }]
                }
            };
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            var scores = history.map(function(r) { return r.results ? (r.results.docScore || 0) : 0; });
            var totalScore = scores.reduce(function(s, p) { return s + p; }, 0);
            var avgScore = Math.round(totalScore / scores.length);
            var maxVal = Math.max.apply(null, scores);
            var bestIdx = scores.indexOf(maxVal);

            var performance = this._t('perf_developing');
            if (avgScore >= 55) performance = this._t('perf_competent');
            if (avgScore >= 70) performance = this._t('perf_strong');
            if (avgScore >= 85) performance = this._t('perf_executive');

            var insights = [];
            if (avgScore >= 70) insights.push(this._t('insight_high'));
            else if (avgScore >= 45) insights.push(this._t('insight_mid'));
            else insights.push(this._t('insight_low'));

            insights.push(this._t('insight_best', { doc: this._round(bestIdx).title }));

            var reductions = history.map(function(r) { return r.results ? (r.results.wordReduction || 0) : 0; });
            var avgReduction = Math.round(reductions.reduce(function(s, v) { return s + v; }, 0) / reductions.length);
            insights.push(this._t('insight_reduction', { pct: avgReduction }));

            return { totalScore: totalScore, avgScore: avgScore, performance: performance, insights: insights };
        }

        formatCompletionMessage(summary) {
            var h = '<div class="rewritelab-sim-summary">';
            h += '<h3>' + this._t('summary_title') + '</h3>';
            h += '<p><strong>' + this._t('summary_performance') + ':</strong> ' + (summary.performance || '') + '</p>';
            h += '<p><strong>' + this._t('summary_avg_score') + ':</strong> ' + (summary.avgScore || 0) + ' / 100</p>';
            if (summary.insights && summary.insights.length) {
                h += '<ul>';
                for (var i = 0; i < summary.insights.length; i++) h += '<li>' + summary.insights[i] + '</li>';
                h += '</ul>';
            }
            h += '</div>';
            return h;
        }

        getHint(state, results) {
            if (!results) return null;
            if (results.docScore < 35) return this._t('hint_low_score');
            if (results.passivePercent > 30) return this._t('hint_passive');
            if (results.wordReduction < 25) return this._t('hint_verbose');
            if (results.jargonCount > 2) return this._t('hint_jargon');
            if (results.docScore >= 80) return this._t('hint_great');
            return null;
        }

        getHistoryTableConfig() {
            var self = this;
            return [
                { key: 'results.docTitle', label: self._t('col_document'), i18nKey: 'col_document' },
                { key: 'results.category', label: self._t('col_focus'), i18nKey: 'col_focus' },
